function updateMollyReadout(sprite,textValue){if(!sprite)return;const {canvas,texture}=sprite.userData,context=canvas.getContext('2d'),text=String(textValue);context.clearRect(0,0,canvas.width,canvas.height);context.fillStyle='rgba(5,12,13,.94)';context.fillRect(4,4,504,152);context.strokeStyle=text.includes('ACTIVE')||text.includes('POWERED')?'#63e3a2':text.includes('LOCK')?'#ee6157':'#7fdce5';context.lineWidth=7;context.strokeRect(7,7,498,146);context.fillStyle='#ecf8f2';context.font='700 34px monospace';context.textAlign='center';context.textBaseline='middle';context.fillText(text,256,80);texture.needsUpdate=true;sprite.userData.text=text}
