function mollyComputerStatus(number,status){const computer=mollyComputers.find(entry=>entry.number===number);if(!computer)return;computer.status=status;computer.indicator.material.color.setHex(status==='override'?0x42db91:status==='hacked'?0xd12b31:0x4ccfe2);computer.indicator.material.emissive.setHex(status==='override'?0x1aa462:status==='hacked'?0x8b1118:0x176779);computer.indicator.material.emissiveIntensity=3;updateMollyReadout(computer.statusLabel,`COMPUTER ${mollyComputerLabel(number)} · ${status==='override'?'OVERRIDE ACTIVE':status==='hacked'?'LOCK ACTIVE':'STANDBY'}`)}
function updateMollyProgressBoard(){mollyProgressLights.forEach((lamp,index)=>{const active=molly.levers.includes(index);lamp.material.color.setHex(active?0x54e39b:0x6a2323);lamp.material.emissive.setHex(active?0x25a96b:0x4b1111);lamp.material.emissiveIntensity=active?4:.65});updateMollyReadout(mollyFinalStatus,molly.finalUnlocked?'EXIT POWERED · DOOR READY':`EXIT POWER · ${molly.levers.length}/3 LEVERS`)}
function hackMollyComputer(number){if(molly.overridden.includes(number))return;const index=mollyDoorForComputer(number);if(!molly.hacked.includes(number))molly.hacked.push(number);mollyComputerStatus(number,'hacked');if(index>=0&&!molly.overridden.includes(number))setMollyDoor(index,false);playMollySound('door');document.querySelector('#prompt').textContent=`COMPUTER ${mollyComputerLabel(number)} HACKED · LINKED SHUTTER CLOSED`;saveMolly()}
function openMollyOverride(number){if(!molly.codesRead)return document.querySelector('#prompt').textContent='THE TERMINAL REQUESTS A CODE · USE THE CLATTERING CODE MACHINE IN RECEPTION FIRST';if(molly.overridden.includes(number))return document.querySelector('#prompt').textContent=`COMPUTER ${mollyComputerLabel(number)} OVERRIDE HOLDS · MOLLY CANNOT UNDO IT`;controls.unlock();base('ELECTRICAL SECTION',`COMPUTER ${mollyComputerLabel(number)} OVERRIDE`,'Enter this terminal’s four-digit unlock code. The computer number on Molly’s face identifies her destination; it is not the code.');const input=document.createElement('input');input.maxLength=4;input.inputMode='numeric';input.placeholder='_ _ _ _';const button=document.createElement('button');button.textContent='OVERRIDE LINKED SHUTTER';button.onclick=()=>{if(input.value.trim()!==mollyComputerCode(number)){feedback.textContent='ACCESS DENIED · The terminal alarm gives Molly this exact location.';playMollySound('error');mollyHearSound(mollyComputers.find(entry=>entry.number===number).mesh.position,1.35,'terminal alarm');return}molly.overridden.push(number);molly.hacked=molly.hacked.filter(value=>value!==number);mollyComputerStatus(number,'override');const index=mollyDoorForComputer(number);if(index>=0)setMollyDoor(index,true);saveMolly();dlg.close();pickupTone();document.querySelector('#prompt').textContent=`COMPUTER ${mollyComputerLabel(number)} OVERRIDDEN · LINKED SHUTTER PERMANENTLY OPEN`;molly.lastSound=[...MOLLY_COMPUTER_POSITIONS[number-1]];molly.soundStrength=1.2;molly.route=[];molly.routeTarget='';molly.phase='listening';mollySetDisplay('00');cancelMollyFlare();startMollyFlare('agitated','resume-search')};body.append(input,button)}
function triggerMollyCodeMachine(){molly.codesRead=true;saveMolly();playPurgeCrash();mollyHearSound(new THREE.Vector3(0,0,21.5),1.4,'the code machine');objective.textContent=`Printed codes: C02 ${mollyComputerCode(2)} · C04 ${mollyComputerCode(4)} · C06 ${mollyComputerCode(6)}. Reach each lever; override only shutters Molly has locked.`;message('DOOR OVERRIDE CODES',`COMPUTER 02 · ${mollyComputerCode(2)}   //   COMPUTER 04 · ${mollyComputerCode(4)}   //   COMPUTER 06 · ${mollyComputerCode(6)}. The slip is kept. Molly heard the machine, not your new position.`)}
