function mollyDroneDistraction(){if(!molly||hotelSideScene!=='molly-electrical')return false;const route=MOLLY_DRONE_ROUTES[molly.droneRouteIndex%MOLLY_DRONE_ROUTES.length];molly.droneRouteIndex++;openMollyDroneLatch();playMollySound('intercom');mollyHearSound(new THREE.Vector3(...route.position),1,'the drone beep');if(!molly.cameraView){molly.cameraView={kind:'drone',label:route.label,position:[route.position[0],4.6,route.position[2]+2.2],look:[route.position[0],1,route.position[2]],playerPosition:[camera.position.x,camera.position.y,camera.position.z],playerQuaternion:[camera.quaternion.x,camera.quaternion.y,camera.quaternion.z,camera.quaternion.w],timer:4};controls.unlock()}document.querySelector('#prompt').textContent=`DRONE · ${route.label} · SHORTCUT LATCH RELEASED · AUTO-RECALL IN 4 SECONDS`;saveMolly();return true}
function startMollyCameraFeed(){if(molly.cameraView)return;const index=molly.cameraFeedIndex%MOLLY_CAMERA_FEEDS.length,feed=MOLLY_CAMERA_FEEDS[index];molly.cameraFeedIndex=(index+1)%MOLLY_CAMERA_FEEDS.length;molly.cameraView={kind:'security',feedIndex:index,label:feed.label,position:feed.position,look:feed.look,playerPosition:[camera.position.x,camera.position.y,camera.position.z],playerQuaternion:[camera.quaternion.x,camera.quaternion.y,camera.quaternion.z,camera.quaternion.w],timer:7};controls.unlock();document.querySelector('#prompt').textContent=`CAM ${String(index+1).padStart(2,'0')} · ${feed.label} · LIVE · RETURNING IN 7 SECONDS`;saveMolly()}
