function pullMollyLever(index){if(molly.levers.includes(index))return;molly.levers.push(index);const lever=mollyLevers[index];if(lever){lever.rotation.z=-.72;lever.userData.indicator.material.color.setHex(0x55e7a0);lever.userData.indicator.material.emissive.setHex(0x26a96c);lever.userData.housing.material.emissive.setHex(0x174f36);updateMollyReadout(lever.userData.statusLabel,`MAIN LEVER ${index+1} · ENGAGED`)}pickupTone();playMollySound('door');if(molly.levers.length===3){molly.finalUnlocked=true;cancelMollyFlare();document.body.classList.remove('molly-hacking','molly-listening');objective.textContent='All three levers hold. Reach the powered final exit; Molly cannot cancel it.';document.querySelector('#prompt').textContent='FINAL EXIT POWERED · NO ADDITIONAL CODE REQUIRED';molly.phase='final-travel';molly.route=[];molly.routeTarget='';molly.lastSound=[...MOLLY_COMPUTER_POSITIONS[5]];mollySetDisplay('00');horrorStinger()}else document.querySelector('#prompt').textContent=`LEVER ${index+1} ENGAGED PERMANENTLY · ${3-molly.levers.length} REMAIN`;updateMollyProgressBoard();saveMolly();setMollyHud()}
function handleMolly(part,trigger){if(!molly||molly.dying)return;if(part==='code-machine')return triggerMollyCodeMachine();if(part.startsWith('computer:'))return openMollyOverride(Number(part.slice(9)));if(part.startsWith('lever:'))return pullMollyLever(Number(part.slice(6)));if(part==='hammer'){if(molly.hammerTaken)return;molly.hammerTaken=true;hotelRunItems.add('electrical-hammer');saveHotelRun();saveMolly();updateInventory();playFirstPersonAction('pickup','electrical-hammer',.7);return document.querySelector('#prompt').textContent='INSULATED HAMMER ACQUIRED · YELLOW-BLACK WINDOW FRAMES ARE BREAKABLE'}if(part==='drone'){if(molly.droneTaken)return;molly.droneTaken=true;hotelRunItems.add('drone-controller');saveHotelRun();saveMolly();updateInventory();playFirstPersonAction('pickup','drone-controller',.7);return document.querySelector('#prompt').textContent='MAINTENANCE DRONE ACQUIRED · SELECT IT AND PRESS Q FOR A FEED, LATCH, AND DISTRACTION'}if(part==='window'){if(molly.brokenWindow)return;if(!molly.hammerTaken)return document.querySelector('#prompt').textContent='YELLOW-BLACK SHORTCUT WINDOW · INSULATED HAMMER REQUIRED';molly.brokenWindow=true;playFirstPersonAction('use','electrical-hammer',.62);playPurgeCrash();mollyHearSound(new THREE.Vector3(24,0,-16),1.6,'the breaking window');const pane=roomGroup.getObjectByName('Molly breakable safety window'),blocker=roomGroup.getObjectByName('Molly breakable window blocker');if(pane)pane.visible=false;blocker?.removeFromParent();solidColliders=solidColliders.filter(collider=>collider.mesh!==blocker);saveMolly();return document.querySelector('#prompt').textContent='SHORTCUT WINDOW OPEN · CLIMB THROUGH AND MOVE · MOLLY IS COMING TO THE CRASH'}if(part==='camera')return startMollyCameraFeed();if(part==='exit'){if(!molly.finalUnlocked)return document.querySelector('#prompt').textContent=`FINAL EXIT UNPOWERED · ${3-molly.levers.length} LEVERS REMAIN`;return beginHotelRoomPassage(trigger,leaveMollySection)}}
